      "Go to Definition failed": "\u5B9A\u7FA9\u3078\u79FB\u52D5\u306B\u5931\u6557\u3057\u307E\u3057\u305F",
      "Peek Definition failed": "\u5B9A\u7FA9\u306E\u30D7\u30EC\u30D3\u30E5\u30FC\u306B\u5931\u6557\u3057\u307E\u3057\u305F",
      "No references": "\u53C2\u7167\u304C\u3042\u308A\u307E\u305B\u3093",
