      "Snapshot created": "\u30B9\u30CA\u30C3\u30D7\u30B7\u30E7\u30C3\u30C8\u3092\u4F5C\u6210\u3057\u307E\u3057\u305F",
      "No snapshot for this file yet": "\u3053\u306E\u30D5\u30A1\u30A4\u30EB\u306E\u30B9\u30CA\u30C3\u30D7\u30B7\u30E7\u30C3\u30C8\u306F\u307E\u3060\u3042\u308A\u307E\u305B\u3093",
      "No cursor in the editor": "\u30A8\u30C7\u30A3\u30BF\u30FC\u306B\u30AB\u30FC\u30BD\u30EB\u304C\u3042\u308A\u307E\u305B\u3093",
