      "Current Version": "\u5F53\u524D\u7248\u672C",
      "Latest Version": "\u6700\u65B0\u7248\u672C",
      "Released": "\u53D1\u5E03\u65E5\u671F",
      "Release Notes": "\u53D1\u5E03\u8BF4\u660E",
      "Download & Install": "\u4E0B\u8F7D\u5E76\u5B89\u88C5",
      "Undo Last Edit": "\u64A4\u9500\u4E0A\u6B21\u7F16\u8F91",
      "Redo Last Edit": "\u91CD\u505A\u4E0A\u6B21\u7F16\u8F91",
      "Chat Settings": "\u804A\u5929\u8BBE\u7F6E",
      "Show Chat Debug View": "\u663E\u793A\u804A\u5929\u8C03\u8BD5\u89C6\u56FE",
      "Show tips": "\u663E\u793A\u63D0\u793A",
      "Hide tips": "\u9690\u85CF\u63D0\u793A",
      "Session Info": "\u4F1A\u8BDD\u4FE1\u606F",
      "Reserved for response": "\u4E3A\u54CD\u5E94\u4FDD\u7559",
      "Compact Conversation": "\u538B\u7F29\u5BF9\u8BDD",
      "Running": "\u8FD0\u884C\u4E2D",
      "Finished": "\u5DF2\u5B8C\u6210",
      "Stopped": "\u5DF2\u505C\u6B62",
      "depth {n}": "\u6DF1\u5EA6 {n}",
      "background": "\u540E\u53F0",
      "Spawned by the main agent": "\u7531\u4E3B\u4EE3\u7406\u751F\u6210",
      "Spawned by a subagent at depth {n}": "\u7531\u6DF1\u5EA6 {n} \u7684\u5B50\u4EE3\u7406\u751F\u6210",
      "Prompt": "\u63D0\u793A\u8BCD",
      "Tool calls ({n})": "\u5DE5\u5177\u8C03\u7528 ({n})",
