      "Refactor tanpa ubah perilaku": "\u5728\u4E0D\u6539\u53D8\u884C\u4E3A\u7684\u524D\u63D0\u4E0B\u91CD\u6784",
      "Tulis dokumentasi": "\u7F16\u5199\u6587\u6863",
