      "0 subagent di panel": "\u0644\u0627 \u0648\u0643\u0644\u0627\u0621 \u0641\u0631\u0639\u064A\u0648\u0646 \u0641\u064A \u0627\u0644\u0644\u0648\u062D\u0629",
