      "Lihat isi sebuah folder": "\u0627\u0637\u0651\u0644\u0639 \u0639\u0644\u0649 \u0645\u062D\u062A\u0648\u0649 \u0645\u062C\u0644\u062F",
      "Cari lewat rg / git / find": "\u0627\u0628\u062D\u062B \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 rg / git / find",
      "Lihat keluaran terminal pane": "\u0627\u0637\u0651\u0644\u0639 \u0639\u0644\u0649 \u0625\u062E\u0631\u0627\u062C \u0644\u0648\u062D \u0627\u0644\u0637\u0631\u0641\u064A\u0629",
      "Error dan peringatan editor": "\u0623\u062E\u0637\u0627\u0621 \u0627\u0644\u0645\u062D\u0631\u0631 \u0648\u062A\u062D\u0630\u064A\u0631\u0627\u062A\u0647",
      "Kanal Output panel bawah": "\u0642\u0646\u0627\u0629 \u0627\u0644\u0625\u062E\u0631\u0627\u062C \u0641\u064A \u0627\u0644\u0644\u0648\u062D\u0629 \u0627\u0644\u0633\u0641\u0644\u064A\u0629",
      "Skill yang tersedia": "\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u062A\u0627\u062D\u0629",
      "Catatan lintas sesi": "\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u062A\u0628\u0642\u0649 \u0628\u064A\u0646 \u0627\u0644\u062C\u0644\u0633\u0627\u062A",
      "Persona: identitas": "\u0627\u0644\u0647\u0648\u064A\u0629",
      "Persona: cara kerja": "\u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u0639\u0645\u0644",
      "Persona: salin": "\u0646\u0633\u062E",
      "Persona: baru": "+ \u0634\u062E\u0635\u064A\u0629 \u062C\u062F\u064A\u062F\u0629",
      "Persona: bawaan": "\u0645\u062F\u0645\u062C",
      "Subagent: kirim lanjutan": "\u0625\u0631\u0633\u0627\u0644",
      "Subagent: alat": "\u0627\u0644\u0623\u062F\u0648\u0627\u062A",
      "Subagent: nama": "\u0627\u0644\u0627\u0633\u0645",
      "Subagent: deskripsi": "\u0627\u0644\u0648\u0635\u0641",
