      "theme.translucentHint": "\u30C6\u30AD\u30B9\u30C8\u304C\u8AAD\u307F\u306B\u304F\u3044\u5834\u5408\u306F\u30AA\u30D5\u306B\u3057\u307E\u3059",
      "theme.backgroundActiveInfo": "\u80CC\u666F\u304C\u6709\u52B9\u3067\u3059\u3002\u753B\u50CF\u304C\u898B\u3048\u308B\u3088\u3046\u30D1\u30CD\u30EB\u3092\u5C11\u3057\u534A\u900F\u660E\u306B\u3057\u3001\u30C6\u30AD\u30B9\u30C8\u306F\u5341\u5206\u306A\u30B3\u30F3\u30C8\u30E9\u30B9\u30C8\u306E\u3042\u308B\u8272\u306E\u4E0A\u306B\u8868\u793A\u3055\u308C\u307E\u3059\u3002",
      "theme.active": "\u30A2\u30AF\u30C6\u30A3\u30D6\u306A\u30C6\u30FC\u30DE:",
