      "general.uiLang": "\u754C\u9762\u8BED\u8A00",
      "general.zoom": "\u7F29\u653E",
      "general.restoreSession": "\u542F\u52A8\u65F6\u6062\u590D\u4F1A\u8BDD",
      "general.checkUpdates": "\u81EA\u52A8\u68C0\u67E5\u66F4\u65B0",
      "general.openDataFolder": "\u6253\u5F00\u6570\u636E\u6587\u4EF6\u5939",
      "editor.tabSize": "\u5236\u8868\u7B26\u5927\u5C0F",
      "editor.insertSpaces": "\u4F7F\u7528\u7A7A\u683C\u4EE3\u66FF\u5236\u8868\u7B26",
      "editor.wordWrap": "\u81EA\u52A8\u6362\u884C",
