      "theme.strengthPreset": "\u0625\u0639\u062F\u0627\u062F \u0627\u0644\u0642\u0648\u0629 \u0627\u0644\u0645\u0633\u0628\u0642",
      "theme.strengthFaint": "\u062E\u0627\u0641\u062A\u0629",
      "theme.strengthMedium": "\u0645\u062A\u0648\u0633\u0637\u0629",
      "theme.strengthClear": "\u0648\u0627\u0636\u062D\u0629",
      "theme.backgroundStrength": "\u0642\u0648\u0629 \u0627\u0644\u062E\u0644\u0641\u064A\u0629",
      "theme.fitMode": "\u0648\u0636\u0639 \u0627\u0644\u0645\u0644\u0627\u0621\u0645\u0629",
      "theme.fitHint": "\u0627\u0644\u0645\u0644\u0621 \u064A\u063A\u0637\u064A \u0627\u0644\u0645\u0633\u0627\u062D\u0629\u060C \u0648\u0627\u0644\u0643\u0627\u0645\u0644 \u064A\u0639\u0631\u0636 \u0627\u0644\u0635\u0648\u0631\u0629 \u0643\u0627\u0645\u0644\u0629\u060C \u0648\u0627\u0644\u0623\u0635\u0644\u064A \u064A\u0633\u062A\u062E\u062F\u0645 \u062D\u062C\u0645\u0647\u0627 \u0627\u0644\u0623\u0635\u0644\u064A",
      "theme.backgroundFitMode": "\u0648\u0636\u0639 \u0645\u0644\u0627\u0621\u0645\u0629 \u0627\u0644\u062E\u0644\u0641\u064A\u0629",
